(r=>{lsd&&r&&r.blocks&&r.blockEditor&&r.element&&lsd.shortcodes.forEach(function(e,o){var t='[listdom id="'+e.id+'"]';r.blocks.registerBlockType("listdom/shortcodes-"+o,{apiVersion:3,title:e.title.toLowerCase().replace("/(^([a-zA-Zp{M}]))|([ -][a-zA-Zp{M}])/g",function(e){return e.toUpperCase().replace(/-/g," ")}),icon:"editor-code",category:"lsd.be.category",edit:function(){return r.element.createElement("div",r.blockEditor.useBlockProps(),t)},save:function(){return t}})})})(window.wp,jQuery);